import{z as s,x as i,o,c as A,q as E,j as t,D as a,d as c,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"ELF 格式","description":"","frontmatter":{"title":"ELF 格式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/elf-format.md","filePath":"cs/elf-format.md","lastUpdated":1791413859000}'),n={name:"cs/elf-format.md"};function p(B,e,_,D,m,f){const d=i("Mermaid");return o(),A("div",null,[e[2]||(e[2]=E('<h1 id="elf-格式" tabindex="-1">ELF 格式 <a class="header-anchor" href="#elf-格式" aria-label="Permalink to &quot;ELF 格式&quot;">​</a></h1><div class="epigraph"><p>ELF 是 Unix 上可重定位、可执行与共享对象的容器：ELF 头、程序头、节头、符号与重定位表按约定排布。</p><footer>—— 据 System V ABI 与 ELF 规范；Levine；主干目标文件讨论整理</footer></div><p>上一课<a href="/cs/icf-identical-code-folding">ICF</a>在节上操作，但「节」在文件里长什么样还没钉死。缺口是<strong>文件格式本身</strong>：<code>Elf64_Ehdr</code>、<code>Phdr</code>、<code>Shdr</code>、节名 <code>.text</code>。本课钉结构，加载下一课。不把 PE/Mach-O 写完，只点名对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>产物链各有各的类型：汇编器/编译器写可重定位的 <code>ET_REL</code>，链接器写 <code>ET_EXEC</code>/<code>ET_DYN</code>。关键设计是两套表服务两类读者：程序头给内核与 <code>ld.so</code>，它们只关心哪段加载到哪、什么权限；节头给链接器、调试器、<code>objdump</code>，它们关心符号与重定位。两套表同住一个文件却互不依赖——这就是缺口的形状，不是 ICF 算法。</p><p><span class="marginnote">术语翻译：程序头表回答「运行时怎么装」——哪段加载到哪个虚拟地址、可读可写还是可执行；节头表回答「链接和调试怎么用」——<code>.text</code>、<code>.data</code>、符号、重定位各在哪。同一个文件两套目录，各服务一类读者，互不依赖。</span></p><p>符号表成对：<code>.symtab</code> 完整，<code>.dynsym</code> 动态子集，各自伴随字符串表存名字。</p><h3 id="节头可被-strip" tabindex="-1">节头可被 strip <a class="header-anchor" href="#节头可被-strip" aria-label="Permalink to &quot;节头可被 strip&quot;">​</a></h3><p>加载不依赖节头：strip 之后程序照常运行，只是调试与符号化困难。反过来才要小心——节存在不代表会被加载，<code>.comment</code>、<code>.symtab</code> 都不进内存。不要认为「没有节就不能执行」。</p><p><span class="marginnote">数字实例：ELF 魔数是文件开头 4 个字节 <code>0x7F &#39;E&#39; &#39;L&#39; &#39;F&#39;</code>，内核读 ELF 文件的第一件事就是核对它，不对直接拒绝执行。所谓「约定排布」，就是从这 4 个字节开始，每个字段的偏移与含义都写死在规范里，解析器照单取数。</span></p><p><span class="marginnote">ELF 规范。<code>readelf -a</code>。本课 64 位小端为例。不进 Windows PE 细节。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>解析次序固定：读 <code>e_ident</code> 校验魔数、类、端序，再沿 <code>e_phoff</code>/<code>e_shoff</code> 跳到两张表，动态可执行再进 <code>PT_DYNAMIC</code> 解析 <code>DT_*</code> 条目拿依赖与重定位。工具：<code>readelf</code> 看结构、<code>objdump -d</code> 看反汇编。与链接脚本是上下游：脚本输出的节最终填进这些表。</p>',13)),(o(),t(l,null,{default:a(()=>[r(d,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20EHDR%5B%22ELF%20%E5%A4%B4%22%5D%20--%3E%20PHDR%5B%22%E7%A8%8B%E5%BA%8F%E5%A4%B4%20%E2%86%92%20%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20EHDR%20--%3E%20SHDR%5B%22%E8%8A%82%E5%A4%B4%20%E2%86%92%20%E9%93%BE%E6%8E%A5%2F%E8%B0%83%E8%AF%95%22%5D%0A%20%20SHDR%20--%3E%20SYM%5B%22%E7%AC%A6%E5%8F%B7%20%2F%20%E9%87%8D%E5%AE%9A%E4%BD%8D%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E('<p>与链接脚本：脚本输出的节最终填进这些表。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>段对齐由 <code>p_align</code> 声明，错一页就无法整页映射与共享；<code>PT_INTERP</code> 指向动态加载器路径，内核先把 <code>ld.so</code> 映进来再交控制权，静态可执行没有 INTERP，入口直接是程序自身。这些约定彼此咬合，所以不要手改 ELF 字段当「优化」——校验散在内核与加载器各处，改错要么拒载、要么运行期才炸。构建系统应调链接器，不做后处理。</p><p><span class="marginnote">为什么重要：<code>p_align</code> 错一页，内核就无法把同一份共享库的代码页在多个进程间共享映射，每个进程都得各占一份物理内存。这类错还往往「能跑」，只是悄悄变慢变肥——所以格式校验失败当场拒载的程序，反而是幸运的。</span></p><p>内核把控制权交给程序入口之前，静态与动态可执行各走哪条路？</p>',5)),(o(),t(l,null,{default:a(()=>[r(d,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E5%86%85%E6%A0%B8%E8%AF%BB%20ELF%20%E5%B9%B6%E6%98%A0%E5%B0%84%E6%AE%B5%22%5D%20--%3E%20Q%7B%22%E6%9C%89%20PT_INTERP%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%97%A0%EF%BC%9A%E9%9D%99%E6%80%81%E9%93%BE%E6%8E%A5%22%7C%20S%5B%22%E5%85%A5%E5%8F%A3%E7%9B%B4%E6%8E%A5%E6%98%AF%E7%A8%8B%E5%BA%8F%E8%87%AA%E8%BA%AB%22%5D%0A%20%20Q%20--%3E%7C%22%E6%9C%89%EF%BC%9A%E5%8A%A8%E6%80%81%E9%93%BE%E6%8E%A5%22%7C%20I%5B%22%E5%85%88%E6%8A%8A%20ld.so%20%E6%98%A0%E8%BF%9B%E5%86%85%E5%AD%98%22%5D%0A%20%20I%20--%3E%20DY%5B%22%E8%A7%A3%E6%9E%90%20PT_DYNAMIC%20%E7%9A%84%20DT_*%20%E6%9D%A1%E7%9B%AE%22%5D%0A%20%20DY%20--%3E%20DEP%5B%22%E8%A3%85%E8%BD%BD%E4%BE%9D%E8%B5%96%E5%85%B1%E4%BA%AB%E5%BA%93%E5%B9%B6%E5%81%9A%E9%87%8D%E5%AE%9A%E4%BD%8D%22%5D%0A%20%20DEP%20--%3E%20J%5B%22%E6%8E%A7%E5%88%B6%E6%9D%83%E6%89%8D%E4%BA%A4%E7%BB%99%E7%A8%8B%E5%BA%8F%E5%85%A5%E5%8F%A3%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[c(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写内核 <code>load_elf_binary</code> 全文，细节归下一课。后课默认：Unix 工具链目标是 ELF。也不把 ELF 当 DWARF 的别名——DWARF 调试信息住在 ELF 节里，是住户不是房子。下一课 ELF 加载：内核如何 <code>mmap</code> 段。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ELF：头 + 程序头（加载）+ 节头（链接/调试）。</li><li>REL/EXEC/DYN 三种。</li><li>动态信息在 <code>PT_DYNAMIC</code>。</li><li>出处：ELF / SysV ABI；Levine。</li></ul>',4))])}const T=s(n,[["render",p]]);export{F as __pageData,T as default};
